CREATE TABLE "Medicine" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "genericName" TEXT, "batchNumber" TEXT NOT NULL, "price" DOUBLE PRECISION NOT NULL, "costPrice" DOUBLE PRECISION NOT NULL, "stockQuantity" INTEGER NOT NULL, "expiryDate" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Medicine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Sale" ("id" TEXT NOT NULL, "totalAmount" DOUBLE PRECISION NOT NULL, "paymentMethod" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "cashierId" TEXT NOT NULL, CONSTRAINT "Sale_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SaleItem" ("id" TEXT NOT NULL, "saleId" TEXT NOT NULL, "medicineId" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "unitPrice" DOUBLE PRECISION NOT NULL, "total" DOUBLE PRECISION NOT NULL, CONSTRAINT "SaleItem_pkey" PRIMARY KEY ("id"));
ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_saleId_fkey" FOREIGN KEY ("saleId") REFERENCES "Sale"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SaleItem" ADD CONSTRAINT "SaleItem_medicineId_fkey" FOREIGN KEY ("medicineId") REFERENCES "Medicine"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
